<?php $characters=$publicCharacters??[];foreach(['isioma'=>'Isioma','ayo'=>'Ayo'] as $key=>$name){if(!isset($characters[$key])){$characters[$key]=['title'=>$name,'gender'=>'Male character','description'=>'Approved character biography to be added.','body'=>'','revealed'=>false];}}?>
<div class="character-grid"><?php $n=0;foreach($characters as $char):$n++;?><article class="character-card"><div class="portrait"><?php if($char['revealed']):?><img src="<?= e(c_media_url($char['portrait'],480)) ?>" srcset="<?= e(c_media_url($char['portrait'],480)) ?> 480w, <?= e(c_media_url($char['portrait'],960)) ?> 960w" sizes="(max-width: 700px) 90vw, 40vw" width="440" height="490" alt="<?= e($char['alt']) ?>" loading="lazy"><?php else:?><img src="<?= e(asset('images/silhouette.svg')) ?>" width="440" height="490" alt="Anonymous silhouette with a question mark; actor unrevealed" loading="lazy"><?php endif;?><span class="portrait-number"><?= e(str_pad((string)$n,2,'0',STR_PAD_LEFT)) ?></span><span class="portrait-status"><?= $char['revealed']?'OFFICIAL CHARACTER REVEAL':'IDENTITY UNREVEALED' ?></span></div><div class="character-caption"><div><h3><?= e($char['title']) ?></h3><p><?= e($char['gender']) ?> · <?= $char['revealed']?e($char['actor']):'Actor not announced' ?></p></div></div><p><?= e($char['description']) ?></p><?php if($char['body']!==''):?><p><?= nl2br(e($char['body'])) ?></p><?php endif;?><?php if($char['revealed']):?><p><?= nl2br(e($char['biography'])) ?></p><a class="text-link" href="<?= e($char['announcement']) ?>">Official announcement →</a><?php endif;?></article><?php endforeach;?></div>
